package nx.updater;
import java.nio.file.*;import java.io.*;import java.util.*;
public final class UpdateConfig {
 public final Path root,work;public final String repository,releaseRepository,channel,installed,platform,protocol;public final Path trustedKey;
 public UpdateConfig(Path root)throws Exception{this.root=root.toAbsolutePath().normalize();work=this.root.resolve(".nx-update");Properties p=new Properties();Path f=this.root.resolve("config/nx-updater.properties");if(Files.isRegularFile(f))try(InputStream in=Files.newInputStream(f)){p.load(in);}repository=p.getProperty("repository","").trim().replaceFirst("^https://github.com/","").replaceFirst("/$","");if(!repository.isEmpty()&&!repository.matches("[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+"))throw new IOException("Repositorio inválido");releaseRepository=p.getProperty("distributionRepository",repository).trim();if(!releaseRepository.isEmpty()&&!releaseRepository.matches("[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+"))throw new IOException("Repositorio de distribución inválido");channel=p.getProperty("channel","DEVELOPMENT");platform="PC_JAVA";protocol="CB4-LAN-3";String v="0.1.0";Path state=work.resolve("installed.properties");if(Files.isRegularFile(state)){Properties q=new Properties();try(InputStream in=Files.newInputStream(state)){q.load(in);}v=q.getProperty("version",v);}new SemVer(v);installed=v;trustedKey=this.root.resolve("config/trusted-release-key.pem");}
 public boolean configured(){return configurationIssue().isEmpty();}
 public String configurationIssue(){if(repository.isEmpty())return "configura repositorio oficial y clave pública";if(releaseRepository.isEmpty())return "distribución pendiente: el repositorio de control es privado";if(!Files.isRegularFile(trustedKey))return "falta la clave pública oficial de publicaciones";return "";}
}
